import java.io.*;import java.util.*;
class Account implements Serializable {private static final long serialVersionUID=1L;private final String name;private final double balance;Account(String n,double b){name=n;balance=b;}String getName(){return name;}double getBalance(){return balance;}}
class AccountService {private ArrayList<Account> accounts=new ArrayList<>();void addAccount(Account a){if(a==null)throw new IllegalArgumentException("Account cannot be null");accounts.add(a);}int getCount(){return accounts.size();}Account getAccount(int i){if(i<0||i>=accounts.size())throw new IllegalArgumentException("Invalid account index");return accounts.get(i);}void saveData(String file)throws IOException{try(ObjectOutputStream out=new ObjectOutputStream(new FileOutputStream(file))){out.writeObject(accounts);}}@SuppressWarnings("unchecked")void loadData(String file)throws IOException,ClassNotFoundException{try(ObjectInputStream in=new ObjectInputStream(new FileInputStream(file))){accounts=(ArrayList<Account>)in.readObject();}}}
public class Main {public static void main(String[] args)throws Exception{AccountService original=new AccountService();original.addAccount(new Account("Om",5000));original.addAccount(new Account("Rahul",3000));original.saveData("accounts.dat");AccountService restored=new AccountService();restored.loadData("accounts.dat");if(original.getCount()!=restored.getCount())throw new AssertionError("Count mismatch");for(int i=0;i<original.getCount();i++){Account a=original.getAccount(i),b=restored.getAccount(i);if(!a.getName().equals(b.getName())||a.getBalance()!=b.getBalance())throw new AssertionError("Data mismatch");}System.out.println("Save and reload test passed!");}}
